def task_func(url=API_URL, from_encoding=None, to_encoding="utf8"):
    response = requests.get(url, timeout=5, verify=False)
    raw_content = response.content

    if not raw_content:
        return {}

    if from_encoding is None:
        detected = chardet.detect(raw_content)
        if detected['encoding'] is None:
            raise ValueError("Unable to detect encoding for non-empty content")
        from_encoding = detected['encoding']

    try:
        decoded = raw_content.decode(from_encoding)
        re_encoded = decoded.encode(to_encoding)
        parsed = json.loads(re_encoded.decode(to_encoding))
    except (UnicodeDecodeError, UnicodeEncodeError, json.JSONDecodeError) as e:
        raise ValueError(f"Encoding or JSON parsing error: {e}")

    return parsed
