import requests
import json
import pandas as pd
import seaborn as sns
import matplotlib.pyplot as plt
HEADERS = {
    'accept': 'application/json'
}
def task_func(url, parameters):
    if not isinstance(url, str) or not url:
        raise Exception("Invalid URL provided.")
    try:
        response = requests.get(url, headers=HEADERS, params=parameters, verify=False)
        response.raise_for_status()
        data = response.json()
    except requests.RequestException as e:
        raise Exception(f"Failed to retrieve data from URL: {e}")
    if not data:
        raise Exception("No data received from API.")
    try:
        df = pd.DataFrame(data)
    except Exception as e:
        raise Exception(f"Failed to convert data to DataFrame: {e}")
    if df.empty:
        raise Exception("DataFrame is empty.")
    numeric_df = df.select_dtypes(include='number')
    if numeric_df.empty:
        raise Exception("No numeric columns for correlation heatmap.")
    corr = numeric_df.corr()
    fig, ax = plt.subplots()
    sns.heatmap(corr, annot=True, fmt=".2f", cmap='coolwarm', ax=ax)
    ax.set_title("Correlation Heatmap")
    return df, ax
